{
  "name": "@madsoftwaredev/opencode-background-subagent",
  "version": "0.2.0",
  "description": "OpenCode V2 plugin that defaults subagents to background execution and highlights their activity above the prompt.",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "subagent",
    "background"
  ],
  "license": "MIT",
  "author": "MadSoftwareDev",
  "type": "module",
  "exports": {
    ".": "./index.ts",
    "./tui": "./tui.tsx"
  },
  "files": [
    "index.ts",
    "tui.tsx",
    "activity.ts",
    "README.md",
    "LICENSE"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/madsoftwaredev/opencode-plugins.git",
    "directory": "packages/background-subagent"
  },
  "homepage": "https://github.com/madsoftwaredev/opencode-plugins/tree/main/packages/background-subagent#readme",
  "bugs": {
    "url": "https://github.com/madsoftwaredev/opencode-plugins/issues"
  },
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "test": "bun test --preload @opentui/solid/preload",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode/plugin": "^2.0.27"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.17",
    "@opentui/solid": ">=0.5.17",
    "solid-js": ">=1.9.12"
  },
  "devDependencies": {
    "@types/bun": "1.3.9",
    "typescript": "5.8.2"
  },
  "publishConfig": {
    "access": "public"
  }
}
